from work import *
c,h=witnesses(11);t=c
for a,b in {r'\unsure{\mathrm{Modf}|\mathrm{Mod}_{f}}':r'\mathrm{Modf}',r's_{\deleted{\unsure{0}}1}':r's_{\unsure{p|1|0}}',r'\text{\unsure{cas|en} }':r'\text{\unsure{en|cas} }',r'\unsure{éventuelles}':'éventuelles',r'\unsure{plus grd}':'plus grd',r'\unsure{dé|de}':'dé',r'\unsure{les structures|la structure}':'la structure',r'\unsure{.}':'.'}.items():t=t.replace(a,b)
t=t.replace('(L)',r'(\mathcal L)').replace(r'\in L',r'\in\mathcal L').replace('L_{',r'\mathcal L_{')
